/// <cts-enable />
import {
  computed,
  handler,
  pattern,
  type Stream,
  Writable,
} from "commonfabric";

// A `map` over the result of a `computed` that reads state of the scope
// `user`: the notes the acting user did not hide, an array of plain values
// generated by the `computed`. The source of the collection is a value of
// a scope key, which the assembly reads as the value it is.

const hide = handler<{ text: string }, { hidden: Writable<string> }>(
  (event, { hidden }) => {
    hidden.set(event.text);
  },
);

interface Output {
  rows: string[];
  hide: Stream<{ text: string }>;
}

export default pattern<{ notes: Writable<{ text: string }[]> }, Output>(
  ({ notes }) => {
    const hidden = new Writable.perUser<string>("");
    const shown = computed(() => {
      const kept: { text: string }[] = [];
      for (const note of notes.get()) {
        if (note.text !== hidden.get()) kept.push(note);
      }
      return kept;
    });
    return {
      rows: shown.map((note) => note.text + "!"),
      hide: hide({ hidden }),
    };
  },
);
